head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.g_ACPT_NO = '';

///////// 2. 초기화 영역 /////////
/* ★Wcraft guide★    
스크립트 수작업 유의사항

*/
scwin.onpageload = function() {
};

scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.MxDataSet_OnLoadCompleted = function(rowcount) {
    try {
        textbox_1.setValue("총 " + rowcount + "건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80204.MxDataSet_OnLoadCompleted" });
    }
};

scwin.MxGrid_1_OnDblClick = function(row, colid) {
    try {
        // 클릭된 값 변수에 셋팅  
        scwin.setContnId(row);
        if (colid === 'FORM_KOR_NM') {

            fn_OpenDisclViewer_MGT(scwin.g_ACPT_NO, 'ULDMGT80204.gfm');
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80204.MxGrid_1_OnDblClick" });
    }
};

scwin.btn_cal_onclick = function(e) {
    try {
        popUpCalendar(txb_date_bg, 'txb_date', 'yyyymmdd'); // alert('image_2.onclick');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80204.btn_cal_onclick" });
    }
};

scwin.btn_sys_search_onclick = function(e) {
    try {
        if (txb_date.getValue() !== "") {
            scwin.listSync(); // alert();

        } else {
            alert("일자를 지정하십시요");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80204.btn_sys_search_onclick" });
    }
};

scwin.btn_toExcel_onclick = function(e) {
    try {
        MxGrid_1.GridToExcel("추출_변환 로그", "", "8");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80204.btn_toExcel_onclick" });
    }
};

